clearClouds: () => {
    if (doc.clouds.length > 0) wholeMapEdit('confirm.clearClouds', () => { for (const cloud of [...doc.clouds]) doc.removeCloud(cloud.id); });
  }

.lab-panel {
  --lab-bg: #0f161a; --lab-bg2: #151f25; --lab-bg3: #1c2830; --lab-line: rgb(255 255 255 / 0.09); --lab-line2: rgb(255 255 255 / 0.16);
  --lab-text: #e3eaee; --lab-muted: #8b9ca4; --lab-accent: #2fc2ab; --lab-accent-ink: #03211c; --lab-warn: #ffc35a; --lab-bad: #ff6f61; --lab-good: #5fd68e;
  position: fixed; z-index: 80; display: flex; flex-direction: column; min-width: 360px; box-sizing: border-box;
  background: var(--lab-bg); color: var(--lab-text); border: 1px solid var(--lab-line2); border-radius: 12px;
  box-shadow: 0 18px 50px rgb(0 0 0 / 0.55), 0 0 0 1px rgb(0 0 0 / 0.4);
  font: 12px/1.4 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif; color-scheme: dark; overflow: hidden;
}

.glass {
  background: linear-gradient(145deg, var(--ui-hi), transparent 42%), var(--ui-bg);
  border: 1px solid var(--ui-border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

.inspect-actions button {
  padding: 8px;
  border-radius: 9px;
  border: 1px solid var(--ui-border);
  background: transparent;
  color: var(--text);
  font-size: 11px;
  cursor: pointer;
}

.inspect-range {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 2px 8px;
  margin-top: 9px;
  color: var(--muted);
  font-size: 11px;
}

@media (max-width: 780px) { .inspector {
    left: 10px;
    right: 10px;
    top: 74px;
    width: auto;
    max-height: calc(100dvh - 210px);
    overflow: auto;
  } }

.rp-panel {
  position: fixed; left: 16px; right: 16px; bottom: calc(var(--v-dock-h, 54px) + 14px); z-index: 40;
  max-width: 1000px; margin: 0 auto; max-height: calc(100vh - var(--v-dock-h, 54px) - var(--v-hud-h, 46px) - 30px); overflow: auto;
  display: grid; gap: 8px; padding: 12px 14px 14px;
  /* Nearly opaque: a panel this full of drawing must not show the tool bars through it. */
  background: rgba(14, 22, 24, 0.97); color: var(--v-text, #eef4f2);
  border: 1px solid var(--v-line, rgba(255, 255, 255, 0.1)); border-radius: var(--v-r, 12px);
  box-shadow: var(--v-shadow, 0 18px 50px rgba(0, 0, 0, 0.45));
  font: 13px/1.3 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif;
}

.rp-keys {
  position: fixed; left: 330px; bottom: 80px; z-index: 41; width: 264px; display: grid; gap: 8px; padding: 12px;
  background: rgba(14, 22, 24, 0.97); color: var(--v-text, #eef4f2); border: 1px solid var(--v-line, rgba(255,255,255,.1));
  border-radius: var(--v-r, 12px); box-shadow: var(--v-shadow, 0 18px 50px rgba(0,0,0,.45));
  font: 13px/1.3 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif;
}

.v2-hud, .v2-dock, .v2-drawer, .v2-toolopts, .v2-pop, .v2-side, .v2-toast {
  pointer-events: auto;
  background: var(--v-bg);
  border: 1px solid var(--v-line);
  box-shadow: var(--v-shadow);
}

.v2-icon > span, .v2-pill > span, .v2-seg-b > span, .v2-tabs.compact .v2-tab.icon:not(.on) > span, .v2-tabs.tight .v2-tab.icon > span, .v2-choice.icon > span,
.v2-verb > span, .v2-act > span {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;
}

.v2-hud {
  position: absolute; top: 12px; left: 12px; right: 12px; height: var(--v-hud-h);
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px;
  padding: 0 8px; border-radius: var(--v-r);
}

.v2-seg-b, .v2-speed-b {
  position: relative; display: grid; place-items: center; min-width: 34px; height: 28px; padding: 0 6px;
  border: 0; border-radius: 999px; background: none; color: var(--v-muted); font-weight: 700; font-size: 14px;
}

.v2-pill, .v2-icon {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  width: 32px; height: 32px; padding: 0; flex: none;
  border: 1px solid var(--v-line); border-radius: 10px; background: var(--v-raise); color: var(--v-text);
}

.v2-dock {
  position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%);
  display: flex; gap: 2px; padding: 4px; border-radius: 14px; max-width: calc(100vw - 24px); overflow-x: auto; scrollbar-width: none;
}

.v2-cat {
  position: relative; display: grid; grid-template-rows: 24px auto; justify-items: center; align-content: center; gap: 3px;
  min-width: 66px; height: 52px; padding: 0 6px; border: 1px solid transparent; border-radius: 10px; background: none; color: var(--v-muted);
}

.v2-drawer {
  position: absolute; left: 50%; bottom: calc(12px + var(--v-dock-h) + 10px); transform: translateX(-50%);
  width: max-content; min-width: 0; max-width: calc(100vw - 24px);
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "head close" "body body"; align-items: center;
  border-radius: var(--v-r); overflow: hidden;
}

.v2-strip {
  flex: 1; min-width: 0; display: flex; gap: 0; padding: 6px 8px; align-items: flex-start;
  overflow-x: auto; overflow-y: hidden;
  scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.v2-card {
  position: relative; display: grid; grid-template-rows: var(--v-card) auto; width: var(--v-card-w); padding: 0; overflow: hidden;
  border: 1px solid var(--v-line); border-radius: 8px; background: var(--v-raise); text-align: center;
}

.v2-verb {
  position: relative; display: grid; place-items: center; width: 32px; height: 32px; padding: 0;
  border: 1px solid var(--v-line); border-radius: var(--v-r-s); background: var(--v-raise);
}

.v2-toolopts {
  position: absolute; left: 12px; bottom: 12px; width: var(--v-opts-w); max-width: calc(100vw - 24px);
  display: grid; gap: 2px; padding: 6px 8px; border-radius: var(--v-r);
  max-height: calc(100dvh - var(--v-hud-h) - 36px); overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain;
  scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.v2-side .inspect-select input[type="number"], .v2-side .inspect-select select {
  width: 100%; height: 32px; padding: 0 8px; border: 1px solid var(--v-line); border-radius: var(--v-r-s);
  background: var(--v-bg-solid); color: var(--v-text); font-size: 13px; color-scheme: dark;
}

@media (781px <= width < 1160px) { .v2 > .v2-dock {
    left: calc(24px + var(--v-opts-w)); transform: none; max-width: calc(100vw - var(--v-opts-w) - 36px);
  } }

.v2-dd {
  display: inline-flex; align-items: center; justify-content: space-between; gap: 6px; height: 30px; max-width: 100%; min-width: 0;
  padding: 0 8px 0 10px; border: 1px solid var(--v-line); border-radius: var(--v-r-s); background: var(--v-raise); color: var(--v-text); font-size: 12.5px;
}

.v2-dd-list {
  position: fixed; z-index: 12; pointer-events: auto; display: grid; gap: 1px; max-height: min(320px, 60dvh); overflow-y: auto; padding: 4px;
  border: 1px solid var(--v-line); border-radius: var(--v-r-s); background: var(--v-bg-solid); box-shadow: var(--v-shadow);
  scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.v2-compass {
  position: absolute; right: 16px; bottom: 16px; width: 52px; height: 52px; padding: 0;
  pointer-events: auto; touch-action: none; border-radius: 50%;
  background: var(--v-bg); border: 1px solid var(--v-line); box-shadow: var(--v-shadow);
  cursor: grab; transition: border-color 120ms ease, transform 120ms ease;
}
